        today = self.Time.date()

        if self.held_option is not None:
            expiry = self.held_option.ID.Date.date()

            if today >= expiry:
                self.no_entry_date = today
                self._submit_exit("Expiration liquidation")
            elif self._is_prior_trading_day(today, expiry) and self.Time.time() >= time(15, 45):
                self._submit_exit("Expiration-eve time stop")
            else:
                self._check_profit_target(slice)

        minute_bar = None
        if slice.Bars.ContainsKey(self.spy):
            minute_bar = slice.Bars[self.spy]

        if minute_bar is None:
            return

        completed = self._add_minute_bar(minute_bar)
        if completed is None:
            return

        bar_end, close = completed

        if not (time(9, 45) <= bar_end.time() <= time(14, 30)):
            return

        if self.no_entry_date == today:
            return

        if self.held_option is not None or self._entry_order_open():
            return

        if not self._is_bullish_crossover(close):
            return

        self._try_enter(slice, close)

    def _add_minute_bar(self, bar):
        start = bar.Time
        local_date = start.date()

        if start.time() < time(9, 30) or start.time() >= time(16, 0):
            return None

        bucket_minute = 30 + ((start.minute - 30) // 5) * 5
        bucket_start = start.replace(
            hour=9,
            minute=bucket_minute,
            second=0,
            microsecond=0
        )

        if self.bucket_start != bucket_start:
            completed = self._complete_bucket()
            self.bucket_date = local_date
            self.bucket_start = bucket_start
            self.bucket_bars = {}
        else:
            completed = None

        self.bucket_bars[start] = bar

        if start.time() == time(15, 59):
            completed = self._complete_bucket()
            self.bucket_start = None
            self.bucket_bars = {}

        return completed

    def _complete_bucket(self):
        if self.bucket_start is None or len(self.bucket_bars) != 5:
            return None

        expected = [
            self.bucket_start + timedelta(minutes=i)
            for i in range(5)
        ]

        if any(t not in self.bucket_bars for t in expected):
            return None

        last_bar = self.bucket_bars[expected[-1]]
        return self.bucket_start + timedelta(minutes=5), last_bar.Close

    def _is_bullish_crossover(self, close):
        self.slow_window.append(close)
        self.fast_window.append(close)

        if len(self.fast_window) < 5 or len(self.slow_window) < 20:
            return False

        current_fast = sum(self.fast_window) / 5.0
        current_slow = sum(self.slow_window) / 20.0

        bullish = (
            self.previous_fast is not None
            and self.previous_slow is not None
            and self.previous_fast <= self.previous_slow
            and current_fast > current_slow
        )

        self.previous_fast = current_fast
        self.previous_slow = current_slow

        return bullish

    def _try_enter(self, slice: Slice, spy_price):
        if not slice.OptionChains:
            self.Debug("Skipped entry: no option chain.")
            return

        current_date = self.Time.date()
        minimum_expiry = current_date + timedelta(days=7)

        contracts = []
        for chain in slice.OptionChains.Values:
            for contract in chain:
                expiry = contract.Expiry.date()

                if (
                    contract.Right == OptionRight.Call
                    and expiry >= minimum_expiry
                    and contract.Strike >= 1.01 * spy_price
                ):
                    contracts.append(contract)

        if not contracts:
            self.Debug("Skipped entry: no qualifying call contract.")
            return

        nearest_expiry = min(contract.Expiry.date() for contract in contracts)
        candidates = [
            contract for contract in contracts
            if contract.Expiry.date() == nearest_expiry
        ]

        selected = min(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )

        if self.Portfolio[selected.Symbol].Invested:
            self.Debug("Skipped entry: selected option is already held.")
            return

        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish five-minute crossover entry"
        )

        self.Debug(
            f"Entry submitted: {selected.Symbol.Value}, "
            f"expiry {nearest_expiry}, strike {selected.Strike}"
        )

    def _check_profit_target(self, slice: Slice):
        if self.held_option is None or self.entry_price is None:
            return

        contract = self._find_contract(slice, self.held_option)
        if contract is None:
            return

        bid = contract.BidPrice
        ask = contract.AskPrice

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0

        if midpoint >= 1.50 * self.entry_price:
            self._submit_exit("50% profit target")

    def _submit_exit(self, reason):
        if self.held_option is None:
            return

        quantity = self.Portfolio[self.held_option].Quantity
        if quantity <= 0:
            return

        if self._exit_order_open():
            if self.exit_ticket is not None:
                self.exit_ticket.Cancel("Replacing exit order")
            self.exit_ticket = None

        self.exit_ticket = self.MarketOrder(
            self.held_option,
            -quantity,
            tag=reason
        )

        self.Debug(f"Exit submitted: {self.held_option.Value}; {reason}")

    def _find_contract(self, slice: Slice, symbol):
        for chain in slice.OptionChains.Values:
            for contract in chain:
                if contract.Symbol == symbol:
                    return contract
        return None

    def _entry_order_open(self):
        if self.entry_ticket is None:
            return False

        return self.entry_ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        )

    def _exit_order_open(self):
        if self.exit_ticket is None:
            return False

        return self.exit_ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        )

    def _is_prior_trading_day(self, current_date, expiry_date):
        date = current_date + timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while date < expiry_date:
            if exchange_hours.IsDateOpen(date):
                return False
            date += timedelta(days=1)

        return date == expiry_date

    def _handle_unexpected_spy_position(self):
        holding = self.Portfolio[self.spy]

        if holding.Quantity != 0:
            self.Debug(
                f"Unexpected SPY equity position detected: {holding.Quantity}. "
                "Liquidating immediately."
            )

            self.MarketOrder(
                self.spy,
                -holding.Quantity,
                tag="Unexpected exercise or assignment liquidation"
            )

    def OnOrderEvent(self, order_event: OrderEvent):
        if self.entry_ticket is not None and order_event.OrderId == self.entry_ticket.OrderId:
            if order_event.Status in (OrderStatus.PartiallyFilled, OrderStatus.Filled):
                if self.held_option is None:
                    self.held_option = order_event.Symbol
                    self.entry_price = order_event.FillPrice

                    self.Debug(
                        f"Entry filled: {self.held_option.Value} at "
                        f"{self.entry_price}"
                    )

            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.entry_ticket = None

        if self.exit_ticket is not None and order_event.OrderId == self.exit_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(f"Exit filled: {order_event.Symbol.Value}")
                self.exit_ticket = None

                if self.Portfolio[order_event.Symbol].Quantity == 0:
                    self.held_option = None
                    self.entry_price = None

            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.exit_ticket = None

        if getattr(order_event, "IsAssignment", False):
            self.Debug(
                f"Unexpected option exercise or assignment: "
                f"{order_event.Symbol.Value}"
            )

            spy_quantity = self.Portfolio[self.spy].Quantity
            if spy_quantity != 0:
                self.MarketOrder(
                    self.spy,
                    -spy_quantity,
                    tag="Assignment liquidation"
                )
