                f"Unexpected exercise or assignment handling: "
                f"{order_event.Symbol}."
            )
            self.HandleUnexpectedEquityPosition()

    def HandleUnexpectedEquityPosition(self):
        if self.equity_liquidation_pending:
            return

        quantity = int(self.Portfolio[self.spy].Quantity)
        if quantity == 0:
            return

        self.equity_liquidation_pending = True
        self.Debug(
            f"Unexpected SPY equity position detected ({quantity}); "
            "liquidating immediately."
        )
        self.MarketOrder(self.spy, -quantity, tag="Unexpected exercise/assignment")

    def OnEndOfAlgorithm(self):
        self.HandleUnexpectedEquityPosition()

    def PreviousTradingDay(self, date):
        exchange_hours = self.Securities[self.spy].Exchange.Hours
        candidate = date - timedelta(days=1)

        while not exchange_hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)

        return candidate

