from AlgorithmImports import *
from collections import deque
from datetime import datetime, timedelta, time as dt_time


class SpyCallMovingAverageCrossover(QCAlgorithm):

    def initialize(self):
        self.set_start_date(2023, 4, 1)
        self.set_end_date(2026, 6, 30)
        self.set_cash(100000)
        self.set_time_zone(TimeZones.NEW_YORK)

        equity = self.add_equity(
            "SPY",
            Resolution.MINUTE,
            Market.USA,
            fill_forward=False,
            leverage=1,
            extended_market_hours=False
        )
        equity.set_data_normalization_mode(DataNormalizationMode.RAW)
        self.spy = equity.symbol

        option = self.add_option(
            "SPY",
            Resolution.MINUTE,
            Market.USA,
            fill_forward=False
        )
        option.set_filter(
            -200,
            200,
            timedelta(days=0),
            timedelta(days=730)
        )
        self.option_symbol = option.symbol

        self.fast_values = deque(maxlen=5)
        self.slow_values = deque(maxlen=20)

        self.minute_bucket = None
        self.entry_ticket = None
        self.exit_ticket = None
        self.held_option = None
        self.entry_price = None
        self.no_entry_today = False

        self.schedule.on(
            self.date_rules.every_day(self.spy),
            self.time_rules.after_market_open(self.spy, 1),
            self._expiration_guard
        )

        self.schedule.on(
            self.date_rules.every_day(self.spy),
            self.time_rules.at(15, 45),
            self._time_stop
        )

    def on_data(self, slice: Slice):
        spy_bar = slice.bars.get(self.spy)

        if spy_bar is not None:
            self._process_spy_minute(spy_bar, slice)

        self._check_profit_target(slice)

    def _process_spy_minute(self, minute_bar, slice):
        end = minute_bar.end_time

        if end.time() < dt_time(9, 31) or end.time() > dt_time(16, 0):
            return

        session_start = datetime(
            end.year, end.month, end.day, 9, 30
        )

        elapsed_minutes = int((end - session_start).total_seconds() / 60)

        if elapsed_minutes < 1:
            return

        bucket_number = (elapsed_minutes + 4) // 5
        bucket_end = session_start + timedelta(minutes=5 * bucket_number)

        if self.minute_bucket is None:
            self.minute_bucket = {
                "end": bucket_end,
                "bars": {}
            }

        if bucket_end != self.minute_bucket["end"]:
            self.minute_bucket = {
                "end": bucket_end,
                "bars": {}
            }

        self.minute_bucket["bars"][end] = minute_bar

        if end != bucket_end:
            return

        expected_times = [
            bucket_end - timedelta(minutes=i)
            for i in range(1, 6)
        ]

        bars = self.minute_bucket["bars"]

        if any(t not in bars for t in expected_times):
            self.debug(
                "Skipped incomplete SPY five-minute bar ending {}".format(
                    bucket_end
                )
            )
            self.minute_bucket = None
            return

        completed_bar = bars[expected_times[-1]]
        close = minute_bar.close

        previous_fast = (
            sum(self.fast_values) / len(self.fast_values)
            if len(self.fast_values) == 5 else None
        )
        previous_slow = (
            sum(self.slow_values) / len(self.slow_values)
            if len(self.slow_values) == 20 else None
        )

        self.fast_values.append(float(close))
        self.slow_values.append(float(close))

        current_fast = (
            sum(self.fast_values) / 5
            if len(self.fast_values) == 5 else None
        )
        current_slow = (
            sum(self.slow_values) / 20
            if len(self.slow_values) == 20 else None
        )

        eligible_time = (
            dt_time(9, 45) <= bucket_end.time() <= dt_time(14, 30)
        )

        bullish_crossover = (
            previous_fast is not None
            and previous_slow is not None
            and current_fast is not None
            and current_slow is not None
            and previous_fast <= previous_slow
            and current_fast > current_slow
        )

        if (
            bullish_crossover
            and eligible_time
            and not self.no_entry_today
        ):
            self._try_enter(slice, float(close))

        self.minute_bucket = None

    def _try_enter(self, slice, spy_price):
        if self.held_option is not None:
            return

        if self.entry_ticket is not None:
            if self.entry_ticket.status in [
                OrderStatus.NEW,
                OrderStatus.SUBMITTED,
                OrderStatus.PARTIALLY_FILLED
            ]:
                return
            self.entry_ticket = None

        chain = slice.option_chains.get(self.option_symbol)

        if chain is None:
            self.debug("Skipped entry: no current SPY option chain")
            return

        current_date = self.time.date()

        expirations = sorted({
            contract.expiry.date()
            for contract in chain
            if (contract.expiry.date() - current_date).days >= 7
        })

        if not expirations:
            self.debug("Skipped entry: no expiration at least seven days away")
            return

        selected_expiry = expirations[0]
        minimum_strike = 1.01 * spy_price

        candidates = [
            contract
            for contract in chain
            if contract.expiry.date() == selected_expiry
            and contract.right == OptionRight.CALL
            and contract.strike >= minimum_strike
        ]

        if not candidates:
            self.debug(
                "Skipped entry: no qualifying call for expiration {}".format(
                    selected_expiry
                )
            )
            return

        selected = sorted(
            candidates,
            key=lambda contract: (
                float(contract.strike),
                str(contract.symbol)
            )
        )[0]

        self.add_option_contract(selected.symbol, Resolution.MINUTE)
        self.entry_ticket = self.market_order(selected.symbol, 1)

        self.debug(
            "Submitted entry: {} expiration={} strike={}".format(
                selected.symbol,
                selected.expiry.date(),
                selected.strike
            )
        )

    def _check_profit_target(self, slice):
        if self.held_option is None or self.entry_price is None:
            return

        if self.exit_ticket is not None:
            if self.exit_ticket.status in [
                OrderStatus.NEW,
                OrderStatus.SUBMITTED,
                OrderStatus.PARTIALLY_FILLED
            ]:
                return
            self.exit_ticket = None

        quote = slice.quote_bars.get(self.held_option)

