            self.held_option,
            -quantity
        )

        self.debug(
            "Time-stop exit submitted for {} before expiration {}".format(
                self.held_option,
                expiry_date
            )
        )

    def _expiration_guard(self):
        self.no_entry_today = False

        if self.held_option is None:
            return

        current_date = self.time.date()
        expiry_date = self.held_option.id.date.date()

        if expiry_date <= current_date:
            self.no_entry_today = True

            quantity = int(self.portfolio[self.held_option].quantity)

            if quantity > 0:
                self._cancel_exit_order()
                self.exit_ticket = self.market_order(
                    self.held_option,
                    -quantity
                )

                self.debug(
                    "Unexpected expiration exposure: liquidating {}".format(
                        self.held_option
                    )
                )

    def _is_trading_day_immediately_before(self, current_date, expiry_date):
        if current_date >= expiry_date:
            return False

        date = expiry_date - timedelta(days=1)

        while date > current_date:
            if self.securities[self.spy].exchange.hours.is_date_open(date):
                return False
            date -= timedelta(days=1)

        return date == current_date

    def _cancel_exit_order(self):
