    def on_order_event(self, order_event):
        if self.entry_ticket is not None:
            if order_event.order_id == self.entry_ticket.order_id:
                if order_event.status == OrderStatus.FILLED:
                    self.held_option = order_event.symbol
                    self.entry_price = float(order_event.fill_price)
                    self.debug(
                        "Entry filled: {} price={:.4f}".format(
