        self.option.SetFilter(
            lambda u: u.IncludeWeeklys()
                       .Strikes(-100, 100)
                       .Expiration(0, 365)
        )

        self.fast_window = deque(maxlen=5)
        self.slow_window = deque(maxlen=20)
        self.previous_fast = None
        self.previous_slow = None

        self.bucket_start = None
        self.bucket_closes = {}

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_symbol = None
        self.entry_price = None
        self.held_expiry = None

        self.blocked_entry_date = None
        self.time_stop_submitted_date = None
        self.expiration_stop_submitted_date = None

    def OnData(self, slice: Slice):
        current_date = self.Time.date()
        current_time = self.Time.time()

        if self.Portfolio[self.spy.Symbol].Quantity != 0:
            quantity = self.Portfolio[self.spy.Symbol].Quantity
            self.Debug("Unexpected SPY equity position detected; liquidating.")
            self.MarketOrder(
                self.spy.Symbol,
                -quantity,
                tag="Unexpected exercise or assignment"
            )

        self._process_held_position(slice)

        spy_bar = None
        if slice.Bars.ContainsKey(self.spy.Symbol):
            spy_bar = slice.Bars[self.spy.Symbol]

        if spy_bar is None:
            return

        completed_bar = self._add_minute_bar(spy_bar)
        if completed_bar is None:
            return

        bar_end = completed_bar["end_time"]
        close = completed_bar["close"]

        self.fast_window.append(close)
        self.slow_window.append(close)

        if len(self.fast_window) < 5 or len(self.slow_window) < 20:
            return

        fast = sum(self.fast_window) / len(self.fast_window)
        slow = sum(self.slow_window) / len(self.slow_window)

        bullish_crossover = (
            self.previous_fast is not None
            and self.previous_slow is not None
            and self.previous_fast <= self.previous_slow
            and fast > slow
        )

        self.previous_fast = fast
        self.previous_slow = slow

        if not bullish_crossover:
            return

        eligible_time = time(9, 45) <= bar_end.time() <= time(14, 30)
        if not eligible_time:
            return

        if self.blocked_entry_date == current_date:
            return

        if self._has_open_entry_order():
            return

        if self.held_symbol is not None and self.Portfolio[self.held_symbol].Quantity > 0:
            return

        self._enter_from_current_chain(slice, close, current_date)

    def _add_minute_bar(self, bar):
        end_time = bar.EndTime
        session_start = datetime.combine(end_time.date(), time(9, 30))
        session_end = datetime.combine(end_time.date(), time(16, 0))

        if end_time <= session_start or end_time > session_end:
            return None

        elapsed_minutes = int((end_time - session_start).total_seconds() // 60)
        bucket_number = max(0, (elapsed_minutes - 1) // 5)
        bucket_start = session_start + timedelta(minutes=bucket_number * 5)
        bucket_end = bucket_start + timedelta(minutes=5)

        if self.bucket_start is None:
            self.bucket_start = bucket_start

        if bucket_start != self.bucket_start:
            completed = self._complete_bucket()
            self.bucket_start = bucket_start
            self.bucket_closes = {}
        else:
            completed = None

        self.bucket_closes[end_time] = float(bar.Close)

        if end_time >= bucket_end:
            if len(self.bucket_closes) == 5:
                completed = self._complete_bucket()
            else:
                completed = None

            self.bucket_start = None
            self.bucket_closes = {}

        return completed

    def _complete_bucket(self):
        if self.bucket_start is None or len(self.bucket_closes) != 5:
            return None

        expected_times = [
            self.bucket_start + timedelta(minutes=i)
            for i in range(1, 6)
        ]

        if any(t not in self.bucket_closes for t in expected_times):
            return None

        return {
            "end_time": self.bucket_start + timedelta(minutes=5),
            "close": self.bucket_closes[expected_times[-1]]
        }

    def _enter_from_current_chain(self, slice, spy_price, current_date):
        chain = slice.OptionChains.get(self.option.Symbol)

        if chain is None:
            self.Debug("Skipped entry: no option chain in current Slice.")
            return

        minimum_expiry = current_date + timedelta(days=7)

        expiries = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Expiry.date() >= minimum_expiry
        })

        if not expiries:
            self.Debug("Skipped entry: no expiration at least 7 calendar days away.")
            return

        selected_expiry = expiries[0]
        minimum_strike = 1.01 * spy_price

        candidates = [
            contract
            for contract in chain
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call at selected expiration.")
            return

        candidates.sort(key=lambda c: (c.Strike, str(c.Symbol)))
        selected = candidates[0]

        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish five-minute SPY crossover"
        )

        self.Debug(
            f"Entry submitted: {selected.Symbol}; "
            f"expiry={selected_expiry}; strike={selected.Strike}"
        )

    def _process_held_position(self, slice):
        if self.held_symbol is None:
            return

        holding = self.Portfolio[self.held_symbol]
        if holding.Quantity <= 0:
            return

        current_date = self.Time.date()
        current_time = self.Time.time()

        if self.held_expiry is None:
            return

        if current_date >= self.held_expiry:
            self.blocked_entry_date = current_date
            if not self._has_open_exit_order():
                self._submit_exit("Expiration liquidation")
            return

        previous_trading_day = self._previous_trading_day(self.held_expiry)

        if (
            current_date == previous_trading_day
            and current_time >= time(15, 45)
            and self.time_stop_submitted_date != current_date
        ):
            self.blocked_entry_date = current_date
            self.time_stop_submitted_date = current_date

            if not self._has_open_exit_order():
                self._submit_exit("Pre-expiration time stop")

            return

        if self._has_open_exit_order():
            return

        contract = None
        chain = slice.OptionChains.get(self.option.Symbol)

        if chain is not None:
            for candidate in chain:
                if candidate.Symbol == self.held_symbol:
                    contract = candidate
                    break

        if contract is None:
            return

        bid = float(contract.BidPrice)
        ask = float(contract.AskPrice)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0

        if self.entry_price is not None and midpoint >= 1.50 * self.entry_price:
            self._submit_exit("50 percent profit target")

    def _submit_exit(self, reason):
        if self.held_symbol is None:
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity <= 0:
            return

        if self._has_open_exit_order():
            self.Transactions.CancelOrder(
                self.exit_ticket.OrderId,
                f"Replacing exit order: {reason}"
            )

        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            -quantity,
            tag=reason
        )

        self.Debug(f"Exit submitted: {reason}; symbol={self.held_symbol}")

