    def _add_minute_bar(self, bar):
        end_time = bar.EndTime
        session_start = datetime.combine(end_time.date(), time(9, 30))
        session_end = datetime.combine(end_time.date(), time(16, 0))

        if end_time <= session_start or end_time > session_end:
            return None

        elapsed_minutes = int((end_time - session_start).total_seconds() // 60)
        bucket_number = max(0, (elapsed_minutes - 1) // 5)
        bucket_start = session_start + timedelta(minutes=bucket_number * 5)
        bucket_end = bucket_start + timedelta(minutes=5)

        if self.bucket_start is None:
            self.bucket_start = bucket_start

        if bucket_start != self.bucket_start:
            completed = self._complete_bucket()
            self.bucket_start = bucket_start
            self.bucket_closes = {}
        else:
            completed = None

        self.bucket_closes[end_time] = float(bar.Close)

        if end_time >= bucket_end:
            if len(self.bucket_closes) == 5:
                completed = self._complete_bucket()
            else:
                completed = None

            self.bucket_start = None
            self.bucket_closes = {}

        return completed

