        self.last_minute = self.Time
        self.bucket_bars.append(minute_bar)

        if len(self.bucket_bars) == 5:
            self.FinishBucket()
            self.bucket = None
            self.bucket_bars = []
            self.last_minute = None

    def FinishBucket(self):
        if not self.bucket_valid or len(self.bucket_bars) != 5:
            return

        end_time = self.last_minute
        start_time = end_time - timedelta(minutes=5)

        consolidated = TradeBar(
            start_time,
            self.spy,
            self.bucket_bars[0].Open,
            max(x.High for x in self.bucket_bars),
            min(x.Low for x in self.bucket_bars),
            self.bucket_bars[-1].Close,
            sum(x.Volume for x in self.bucket_bars),
            timedelta(minutes=5)
        )

        self.OnFiveMinuteBar(consolidated)

    def OnFiveMinuteBar(self, bar):
        prior_fast = self.previous_fast
        prior_slow = self.previous_slow

        self.fast_closes.append(float(bar.Close))
        self.slow_closes.append(float(bar.Close))

        if len(self.slow_closes) < 20:
            return

        current_fast = sum(self.fast_closes) / 5.0
        current_slow = sum(self.slow_closes) / 20.0

        self.previous_fast = current_fast
        self.previous_slow = current_slow

        if prior_fast is None or prior_slow is None:
            return

        bullish_cross = (
            prior_fast <= prior_slow
            and current_fast > current_slow
        )

        if not bullish_cross:
            return

        end_time = bar.EndTime.time()
        if not (time(9, 45) <= end_time <= time(14, 30)):
            return

        if self.blocked_date == self.Time.date():
            return

        if self.held_symbol is not None or self.HasOpenEntry():
            return

