class SpyBullishCrossoverCall(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        spy_security = self.AddEquity("SPY", Resolution.Minute)
        spy_security.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy = spy_security.Symbol

        option_security = self.AddOption("SPY", Resolution.Minute)
        option_security.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-100, 100)
                .Expiration(0, 365)
        )
        self.option = option_security

        self.fast_values = deque(maxlen=5)
        self.slow_values = deque(maxlen=20)

        self.current_bucket_end = None
        self.current_bucket_bars = {}

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_symbol = None
        self.held_expiry = None
        self.entry_price = None

        self.no_entry_date = None
        self.expiration_processed_date = None

    def OnData(self, slice: Slice):
        current_date = self.Time.date()
        current_time = self.Time.time()

        self._process_expiration(current_date)
        self._process_option_exit(slice, current_date, current_time)

        spy_bar = slice.Bars.get(self.spy)
        if spy_bar is not None:
            self._process_minute_bar(spy_bar, slice)

    def _process_minute_bar(self, bar: TradeBar, slice: Slice):
        end_time = bar.EndTime

        if end_time.time() < time(9, 31) or end_time.time() > time(16, 0):
            return

        bucket_end = self._bucket_end(end_time)

        if self.current_bucket_end is not None and bucket_end != self.current_bucket_end:
            self._finalize_bucket(slice)

        if self.current_bucket_end is None:
            self.current_bucket_end = bucket_end
            self.current_bucket_bars = {}

        self.current_bucket_bars[end_time.replace(second=0, microsecond=0)] = bar

        if end_time.replace(second=0, microsecond=0) == bucket_end:
            self._finalize_bucket(slice)

    def _bucket_end(self, end_time: datetime) -> datetime:
        session_start = end_time.replace(
            hour=9, minute=30, second=0, microsecond=0
        )
        minutes_from_open = int((end_time - session_start).total_seconds() / 60)
        bucket_number = (minutes_from_open + 4) // 5
        return session_start + timedelta(minutes=5 * bucket_number)

    def _finalize_bucket(self, slice: Slice):
        bucket_end = self.current_bucket_end
        bars = self.current_bucket_bars

        self.current_bucket_end = None
        self.current_bucket_bars = {}

        if bucket_end is None:
            return

        bucket_start = bucket_end - timedelta(minutes=5)
        expected_times = [
            bucket_start + timedelta(minutes=i)
            for i in range(1, 6)
        ]

        if len(bars) != 5 or any(t not in bars for t in expected_times):
            return

        close = bars[expected_times[-1]].Close
        self.fast_values.append(close)
        self.slow_values.append(close)

        if len(self.fast_values) < 5 or len(self.slow_values) < 20:
            return

        fast_current = sum(self.fast_values) / 5.0
        slow_current = sum(self.slow_values) / 20.0

        if len(self.fast_values) < 6 or len(self.slow_values) < 21:
            return

        previous_fast = (
            sum(list(self.fast_values)[:-1][-5:]) / 5.0
        )
        previous_slow = (
            sum(list(self.slow_values)[:-1][-20:]) / 20.0
        )

        bullish_cross = (
            previous_fast <= previous_slow
            and fast_current > slow_current
        )

        if not bullish_cross:
            return

        bar_end_time = bucket_end.time()
        if not (time(9, 45) <= bar_end_time <= time(14, 30)):
            return

        if self.no_entry_date == self.Time.date():
            return

        if self.held_symbol is not None or self._entry_order_open():
            return

        self._try_enter(slice, close)

    def _try_enter(self, slice: Slice, spy_price: float):
        chain = None

        try:
            chain = slice.OptionChains.get(self.option.Symbol)
        except Exception:
            pass

        if chain is None:
            self.Debug("Skipped entry: no current SPY option chain.")
            return

        algorithm_date = self.Time.date()
        minimum_expiry = algorithm_date + timedelta(days=7)

        expirations = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Expiry.date() >= minimum_expiry
        })

        if not expirations:
            self.Debug("Skipped entry: no expiration at least 7 calendar days out.")
            return

        selected_expiry = expirations[0]
        minimum_strike = 1.01 * spy_price

        candidates = [
            contract for contract in chain
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call strike.")
            return

        candidates.sort(
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )
        selected = candidates[0]

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug(
            f"Entry submitted: {selected.Symbol}; "
            f"expiry={selected_expiry}, strike={selected.Strike}"
        )

    def _process_option_exit(
        self,
        slice: Slice,
        current_date,
        current_time
    ):
        if self.held_symbol is None or self.entry_price is None:
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity <= 0:
            return

        contract = None
        try:
            chain = slice.OptionChains.get(self.option.Symbol)
            if chain is not None:
                contract = next(
                    (
                        item for item in chain
                        if item.Symbol == self.held_symbol
                    ),
                    None
                )
        except Exception:
            contract = None

        if (
            contract is not None
            and contract.BidPrice > 0
            and contract.AskPrice > 0
        ):
            midpoint = (contract.BidPrice + contract.AskPrice) / 2.0
            if midpoint >= 1.50 * self.entry_price:
                self._submit_exit("50% profit target")
                return

        if (
            current_time >= time(15, 45)
            and self._is_trading_day_before_expiration(
                current_date, self.held_expiry
            )
        ):
            self._submit_exit("expiration-eve time stop")

    def _process_expiration(self, current_date):
        if self.held_symbol is None or self.held_expiry is None:
            return

        if current_date >= self.held_expiry:
            if self.expiration_processed_date != current_date:
                self.expiration_processed_date = current_date
                self.no_entry_date = current_date
                self._submit_exit("expiration processing liquidation")

    def _is_trading_day_before_expiration(self, current_date, expiry_date):
        if current_date >= expiry_date:
            return False

        next_date = current_date + timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while next_date < expiry_date:
            if exchange_hours.IsDateOpen(
                datetime(next_date.year, next_date.month, next_date.day)
            ):
                return False
            next_date += timedelta(days=1)

        return next_date == expiry_date

    def _submit_exit(self, reason: str):
        if self.held_symbol is None:
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity <= 0:
            return

        if self.exit_ticket is not None:
            status = self.exit_ticket.Status
            if status in (
                OrderStatus.New,
                OrderStatus.Submitted,
                OrderStatus.PartiallyFilled,
                OrderStatus.CancelPending,
            ):
                return

        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            -quantity
        )
        self.Debug(f"Exit submitted: {reason}; symbol={self.held_symbol}")

    def _entry_order_open(self) -> bool:
        if self.entry_ticket is None:
            return False

        return self.entry_ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.CancelPending,
        )

    def OnOrderEvent(self, order_event: OrderEvent):
        if (
            self.entry_ticket is not None
            and order_event.OrderId == self.entry_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.held_symbol = order_event.Symbol
                self.held_expiry = order_event.Symbol.ID.Date.date()
                self.entry_price = order_event.FillPrice
                self.Debug(
                    f"Entry filled: {self.held_symbol}; "
                    f"price={self.entry_price}"
                )
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Rejected,
            ):
                self.entry_ticket = None

        if (
            self.exit_ticket is not None
            and order_event.OrderId == self.exit_ticket.OrderId
            and order_event.Status == OrderStatus.Filled
        ):
            self.Debug(f"Exit filled: {order_event.Symbol}")
            self.exit_ticket = None

            if (
                self.held_symbol is not None
                and self.Portfolio[self.held_symbol].Quantity <= 0
            ):
                self.held_symbol = None
                self.held_expiry = None
                self.entry_price = None

        is_exercise = (
            order_event.OrderType == OrderType.OptionExercise
            or getattr(order_event, "IsAssignment", False)
        )

        if is_exercise:
            self.no_entry_date = self.Time.date()
            equity_quantity = self.Portfolio[self.spy].Quantity

            self.Debug(
                f"Unexpected exercise or assignment handling: "
                f"{order_event.Symbol}"
            )

            if equity_quantity != 0:
                self.MarketOrder(self.spy, -equity_quantity)
