        option.SetFilter(
            lambda u: u.IncludeWeeklys()
                       .Strikes(-200, 200)
                       .Expiration(0, 730)
        )

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)
        self.previous_fast = None
        self.previous_slow = None

        self.bucket_end = None
        self.minute_bars = {}

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_option = None
        self.held_expiry = None
        self.entry_price = None

        self.blocked_entry_date = None
        self.equity_liquidation_ticket = None

    def OnData(self, data: Slice):
        today = self.Time.date()

        # Never intentionally carry an option into its expiration date.
        if self.held_expiry is not None and today >= self.held_expiry:
            self.blocked_entry_date = today
            if (
                self.held_option is not None
                and self.Portfolio[self.held_option].Quantity > 0
            ):
                self.SubmitExit("expiration-day liquidation")

        self.HandleUnexpectedEquityPosition()

        if (
            self.held_option is not None
            and self.Portfolio[self.held_option].Quantity == 0
        ):
            self.held_option = None
            self.held_expiry = None
            self.entry_price = None
            self.exit_ticket = None

        # Expiration-eve time stop.
        if self.held_option is not None and self.held_expiry is not None:
            previous_trading_day = self.PreviousTradingDay(self.held_expiry)

            if (
                today == previous_trading_day
                and self.Time.time() >= time(15, 45)
            ):
                self.SubmitExit("expiration-eve time stop")

        self.EvaluateProfitTarget(data)

        if self.spy not in data.Bars:
            return

        minute_bar = data.Bars[self.spy]
        completed = self.AcceptMinuteBar(minute_bar)

        if completed is None:
            return

        completed_end, completed_close = completed

        self.fast.Update(completed_end, completed_close)
        self.slow.Update(completed_end, completed_close)

        if not self.fast.IsReady or not self.slow.IsReady:
            self.previous_fast = self.fast.Current.Value
            self.previous_slow = self.slow.Current.Value
            return

        current_fast = self.fast.Current.Value
        current_slow = self.slow.Current.Value

        bullish_crossover = (
            self.previous_fast is not None
            and self.previous_slow is not None
            and self.previous_fast <= self.previous_slow
            and current_fast > current_slow
        )

        self.previous_fast = current_fast
        self.previous_slow = current_slow

        if (
            bullish_crossover
            and time(9, 45) <= completed_end.time() <= time(14, 30)
        ):
            self.TryEntry(
                data,
                completed_close,
                completed_end.date()
            )

    def AcceptMinuteBar(self, bar):
        """
        Builds five-minute bars only from five actual consecutive minute bars.
        Missing intervals are discarded and never synthesized.
        """
        end = bar.EndTime.replace(second=0, microsecond=0)

        if end.time() < time(9, 31) or end.time() > time(16, 0):
            return None

        absolute_minute = end.hour * 60 + end.minute
        bucket_end_minute = ((absolute_minute + 4) // 5) * 5

        bucket_end = end.replace(
            hour=bucket_end_minute // 60,
            minute=bucket_end_minute % 60
        )

        if self.bucket_end != bucket_end:
            self.bucket_end = bucket_end
            self.minute_bars = {}

        self.minute_bars[end] = bar

        expected = [
            bucket_end - timedelta(minutes=i)
            for i in range(4, -1, -1)
        ]

        if any(timestamp not in self.minute_bars for timestamp in expected):
            return None

        return bucket_end, self.minute_bars[expected[-1]].Close

    def TryEntry(self, data, spy_price, signal_date):
        if (
            signal_date == self.blocked_entry_date
            or self.held_option is not None
            or self.EntryOrderIsOpen()
        ):
            return

        chains = list(data.OptionChains.Values)

        if not chains:
            self.Debug("Skipped selection: no option chain")
            return

        minimum_expiry = signal_date + timedelta(days=7)
        eligible = []

        for chain in chains:
            for contract in chain:
                if (
                    contract.Right == OptionRight.Call
                    and contract.Expiry.date() >= minimum_expiry
                ):
                    eligible.append(contract)

        if not eligible:
            self.Debug("Skipped selection: no qualifying call expiration")
            return

        selected_expiry = min(
            contract.Expiry.date()
            for contract in eligible
        )

