        self._handle_unexpected_spy_position()
        self._handle_expiration()
        self._handle_time_stop()
        self._handle_profit_target(slice)

        if self.spy.Symbol in slice.Bars:
            self._consume_spy_minute(slice.Bars[self.spy.Symbol], slice)

    def _consume_spy_minute(self, bar, slice):
        minute_end = self.Time.replace(second=0, microsecond=0)
        current_time = minute_end.time()

        if current_time <= time(9, 30) or current_time > time(16, 0):
            return

        minute_number = minute_end.hour * 60 + minute_end.minute
        bucket_end_number = ((minute_number + 4) // 5) * 5
        bucket_end = minute_end.replace(
            hour=bucket_end_number // 60,
            minute=bucket_end_number % 60
        )

        if self.minute_bucket_end is not None and bucket_end != self.minute_bucket_end:
            self._finalize_bucket(slice)

        if self.minute_bucket_end != bucket_end:
            self.minute_bucket_end = bucket_end
            self.minute_bucket = OrderedDict()

        self.minute_bucket[minute_end] = bar

        if len(self.minute_bucket) == 5:
            self._finalize_bucket(slice)

    def _finalize_bucket(self, slice):
        if self.minute_bucket_end is None:
            return

        bars = list(self.minute_bucket.values())
        bucket_end = self.minute_bucket_end
        self.minute_bucket = OrderedDict()
        self.minute_bucket_end = None

        if len(bars) != 5:
            return

        close = bars[-1].Close

        self.closes.append(close)
        if len(self.closes) > self.slow_period:
            self.closes.pop(0)

        if len(self.closes) < self.slow_period:
            return

        fast = sum(self.closes[-self.fast_period:]) / self.fast_period
        slow = sum(self.closes[-self.slow_period:]) / self.slow_period

        bullish_cross = (
            self.previous_fast is not None
            and self.previous_slow is not None
            and self.previous_fast <= self.previous_slow
            and fast > slow
        )

        self.previous_fast = fast
        self.previous_slow = slow

        if not bullish_cross:
            return

        if not (time(9, 45) <= bucket_end.time() <= time(14, 30)):
            return

        self._try_entry(slice, close)

    def _try_entry(self, slice, spy_price):
        current_date = self.Time.date()

        if self.no_entry_date == current_date:
            return

        if self.held_symbol is not None or self.entry_ticket is not None:
            return

        if not slice.OptionChains:
            self.Debug("Skipped entry: no option chain in current Slice.")
            return

        minimum_expiry = current_date + timedelta(days=7)
        candidates = []

        for chain in slice.OptionChains.Values:
            for contract in chain:
                expiry_date = contract.Expiry.date()
                if expiry_date >= minimum_expiry:
                    candidates.append(contract)

        if not candidates:
            self.Debug("Skipped entry: no expiration at least 7 calendar days out.")
            return

        nearest_expiry = min(c.Expiry.date() for c in candidates)

        contracts = [
            c for c in candidates
            if c.Expiry.date() == nearest_expiry
            and c.Right == OptionRight.Call
            and c.Strike >= 1.01 * spy_price
        ]

        if not contracts:
            self.Debug("Skipped entry: no qualifying call at selected expiration.")
            return

        selected = min(
            contracts,
            key=lambda c: (c.Strike, str(c.Symbol))
        )

        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish five-minute crossover entry"
        )

