            return

        if self.exit_ticket is not None:
            return

        quote = self._get_current_option_quote(slice, self.held_symbol)
        if quote is None:
            return

        bid, ask = quote
        midpoint = (bid + ask) / 2

        if midpoint < 1.50 * self.entry_price:
            return

        self._submit_option_exit("50% profit target")

    def _handle_time_stop(self):
        if self.held_symbol is None or self.exit_ticket is not None:
            return

        expiry = self._held_expiry()
        if expiry is None:
            return

        previous_trading_day = self._previous_trading_day(expiry)
        if (
            self.Time.date() == previous_trading_day
            and self.Time.time() >= time(15, 45)
        ):
            self._submit_option_exit("expiration-eve time stop")

    def _handle_expiration(self):
        if self.held_symbol is None:
            return

        expiry = self._held_expiry()
        if expiry is None:
            return

        if self.Time.date() >= expiry:
            self.no_entry_date = self.Time.date()
            self._submit_option_exit("expiration protection")

    def _submit_option_exit(self, reason):
        if self.held_symbol is None or self.exit_ticket is not None:
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity == 0:
            return

        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            -quantity,
            tag=reason
        )

    def _get_current_option_quote(self, slice, symbol):
        for chain in slice.OptionChains.Values:
            for contract in chain:
                if contract.Symbol != symbol:
                    continue

                bid = contract.BidPrice
                ask = contract.AskPrice

                if bid is None or ask is None or bid <= 0 or ask <= 0:
                    return None

                return bid, ask

        return None

    def _held_expiry(self):
        if self.held_symbol is None:
            return None
        return self.held_symbol.ID.Date.date()

    def _previous_trading_day(self, expiry):
        candidate = expiry - timedelta(days=1)
        exchange_hours = self.Securities[self.spy.Symbol].Exchange.Hours

        while not exchange_hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)

        return candidate

    def _handle_unexpected_spy_position(self):
        quantity = self.Portfolio[self.spy.Symbol].Quantity
        if quantity == 0:
            return

        self.Debug("Unexpected SPY exercise/assignment position detected.")

        if self.equity_liquidation_ticket is None:
            self.equity_liquidation_ticket = self.MarketOrder(
                self.spy.Symbol,
                -quantity,
                tag="Unexpected exercise/assignment liquidation"
            )

    def OnOrderEvent(self, order_event):
        order_id = order_event.OrderId

        if self.entry_ticket is not None and order_id == self.entry_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.held_symbol = order_event.Symbol
                self.entry_price = order_event.FillPrice
                self.Debug(
                    f"Entry filled: {self.held_symbol} at {self.entry_price}"
                )

            if order_event.Status in (
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                if order_event.Status != OrderStatus.Filled:
                    self.Debug("Entry order did not fill.")
                self.entry_ticket = None

        if self.exit_ticket is not None and order_id == self.exit_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(
                    f"Exit filled: {order_event.Symbol}, "
                    f"price {order_event.FillPrice}"
                )
                if self.Portfolio[order_event.Symbol].Quantity == 0:
                    self.held_symbol = None
                    self.entry_price = None

            if order_event.Status in (
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.exit_ticket = None

        if (
            self.equity_liquidation_ticket is not None
            and order_id == self.equity_liquidation_ticket.OrderId
            and order_event.Status in (
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid
            )
        ):
            self.equity_liquidation_ticket = None
