        previous_slow = self.slow.Current.Value if self.slow.IsReady else None

        self.fast.Update(bar.EndTime, bar.Close)
        self.slow.Update(bar.EndTime, bar.Close)

        if previous_fast is None or previous_slow is None:
            return
        if not self.fast.IsReady or not self.slow.IsReady:
            return

        bullish_cross = (
            previous_fast <= previous_slow
            and self.fast.Current.Value > self.slow.Current.Value
        )

        end_time = bar.EndTime
        if end_time.hour == 9 and end_time.minute < 45:
            eligible_time = False
        elif end_time.hour < 9 or end_time.hour > 14:
            eligible_time = False
        elif end_time.hour == 14 and end_time.minute > 30:
            eligible_time = False
        else:
            eligible_time = True

        if bullish_cross and eligible_time:
            self.pending_signal = True

    def OnData(self, slice):
        today = self.Time.date()

        self.HandleUnexpectedEquityPosition(today)
        self.HandleExpiration(today)

        self.EvaluateProfitTarget(slice)
        self.EvaluateTimeStop(today)

        if not self.pending_signal:
            return

        self.pending_signal = False

        if today == self.no_entry_date:
            return
        if self.HasOptionPosition() or self.HasOpenOrder(self.entry_ticket):
            return
        if self.HasOpenOrder(self.exit_ticket):
            return

        self.TryEnter(slice, today)

    def TryEnter(self, slice, today):
        chains = slice.OptionChains
        chain = chains.get(self.option_symbol)

        if chain is None:
            self.Debug("Skipped entry: no option chain.")
            return

        minimum_expiry = today + timedelta(days=7)
        expiries = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Expiry.date() >= minimum_expiry
        })

        if not expiries:
            self.Debug("Skipped entry: no expiration at least 7 days out.")
            return

        selected_expiry = expiries[0]
        spy_price = self.Securities[self.spy].Price

