        ):
            return
        if self.time_stop_date == today:
            return

        self.time_stop_date = today
        self.SubmitOptionExit("pre-expiration time stop")

    def HandleExpiration(self, today):
        if self.held_expiry is None:
            return

        if today >= self.held_expiry.date():
            self.no_entry_date = today

            if self.HasOpenOrder(self.entry_ticket):
                self.entry_ticket.Cancel("Expiration processing")

            if self.HasOptionPosition():
                self.SubmitOptionExit("expiration protection")

    def SubmitOptionExit(self, reason):
        if not self.HasOptionPosition():
            return
        if self.HasOpenOrder(self.exit_ticket):
            return

        if self.entry_ticket is not None and self.HasOpenOrder(self.entry_ticket):
            self.entry_ticket.Cancel("Exit requested")

        quantity = self.Portfolio[self.held_option].Quantity
        if quantity == 0:
            return

        self.exit_ticket = self.MarketOrder(
            self.held_option,
            -quantity,
            tag=reason
        )

        self.Debug(
            "Exit submitted: {0}, quantity {1}.".format(
                reason,
                quantity
            )
        )

    def HandleUnexpectedEquityPosition(self, today):
        holding = self.Portfolio[self.spy]
        if holding.Quantity == 0:
            return

        self.no_entry_date = today
        self.Debug(
            "Unexpected SPY exercise/assignment position; liquidating."
        )

        if not self.HasOpenOrderForSymbol(self.spy):
            self.MarketOrder(
                self.spy,
                -holding.Quantity,
                tag="Unexpected exercise or assignment"
            )

    def OnAssignmentOrderEvent(self, assignment_event):
        self.no_entry_date = self.Time.date()
        self.Debug("Unexpected option assignment/exercise received.")

        holding = self.Portfolio[self.spy]
        if holding.Quantity != 0 and not self.HasOpenOrderForSymbol(self.spy):
            self.MarketOrder(
                self.spy,
                -holding.Quantity,
                tag="Assignment liquidation"
            )

    def OnOrderEvent(self, order_event):
        if (
            self.entry_ticket is not None
            and order_event.OrderId == self.entry_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.entry_price = order_event.FillPrice
                self.held_option = order_event.Symbol
                self.held_expiry = self.Securities[
                    order_event.Symbol
                ].Symbol.ID.Date

                self.Debug(
                    "Entry filled: {0} at {1}.".format(
                        order_event.Symbol,
                        self.entry_price
                    )
                )
                self.entry_ticket = None

            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.entry_ticket = None

        if (
            self.exit_ticket is not None
            and order_event.OrderId == self.exit_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.Debug(
                    "Exit filled: {0} at {1}.".format(
                        order_event.Symbol,
                        order_event.FillPrice
                    )
                )
                self.exit_ticket = None
                self.held_option = None
                self.held_expiry = None
                self.entry_price = None
                self.time_stop_date = None

            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.exit_ticket = None

        message = str(getattr(order_event, "Message", "")).lower()
        if (
            getattr(order_event, "IsAssignment", False)
            or "assignment" in message
            or "exercise" in message
        ):
            self.OnAssignmentOrderEvent(order_event)

    def HasOptionPosition(self):
        return (
            self.held_option is not None
            and self.Portfolio[self.held_option].Quantity != 0
        )

    def HasOpenOrder(self, ticket):
        if ticket is None:
            return False

        return ticket.Status not in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        )

    def HasOpenOrderForSymbol(self, symbol):
        return any(
            order.Status not in (
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid
            )
            and order.Symbol == symbol
            for order in self.Transactions.GetOpenOrders()
        )

    def IsImmediatelyPrecedingTradingDay(self, current_date, expiry_date):
        previous_date = expiry_date - timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(previous_date):
            previous_date -= timedelta(days=1)

        return current_date == previous_date
