    def OnFiveMinuteBar(self, sender, bar):
        end_time = bar.EndTime.astimezone(self.TimeZone)

        # Only use regular-session, clock-aligned five-minute bars.
        if end_time.time() < time(9, 35) or end_time.time() > time(16, 0):
            return

        if end_time.minute % 5 != 0:
            return

        if len(self.closes) >= 20:
            self.previous_fast = sum(list(self.closes)[-5:]) / 5.0
            self.previous_slow = sum(self.closes) / 20.0

        self.closes.append(float(bar.Close))

        if len(self.closes) < 20:
            return

        current_fast = sum(list(self.closes)[-5:]) / 5.0
        current_slow = sum(self.closes) / 20.0

        eligible_time = time(9, 45) <= end_time.time() <= time(14, 30)

        if (
            eligible_time
            and self.previous_fast is not None
            and self.previous_slow is not None
            and self.previous_fast <= self.previous_slow
            and current_fast > current_slow
        ):
            self.pending_signal_time = end_time

    def OnData(self, slice):
        self.current_slice = slice
        today = self.Time.date()

        if self.state_date != today:
            self.state_date = today
            self.no_entries_today = False

        self.HandleUnexpectedExerciseOrAssignment()
        self.ProcessExpiration()
        self.ProcessTimeStop()
        self.ProcessProfitTarget()

        if (
            self.pending_signal_time is not None
            and self.pending_signal_time <= self.Time
        ):
            signal_time = self.pending_signal_time
            self.pending_signal_time = None

            if signal_time.date() == today and not self.no_entries_today:
                self.TryEnter(slice)

    def TryEnter(self, slice):
        if self.entry_symbol is not None and self.Portfolio[self.entry_symbol].Invested:
            return

        if self.entry_ticket is not None and not self.entry_ticket.Status.IsClosed():
            return

        if not slice.OptionChains.ContainsKey(self.option_symbol):
